-- Access QueryDef: cipuCn_CtptCnOneInvOneAcNotOld
-- Type: 0

SELECT h.ciKey, h.ciputAccount, h.account_key, h.CountCiKey, j.CntrPrtNum, j.CntrPrtName, j.CnName, j.cn_key, j.ciputCnInv
FROM (SELECT d.ciKey, d.ciputAccount, d.account_key, Count(cipuCn_CtptCnOneInvOne.ciKey) AS CountCiKey FROM (SELECT y.ciKey, y.ciputAccount, y.account_key, ac.ciaKey FROM (SELECT z.ciKey, z.ciputAccount, x.account_key FROM (SELECT a.ciKey, b.ciputAccount FROM cipuCn_CtptCnOneInvOne AS a INNER JOIN CnInvPmtUplTblNull AS b ON (a.CntrPrtNum = b.ciputCntrPrtNum) AND (a.CnName = b.ciputCnName) AND (a.ciputCnInv = b.ciputCnInv) GROUP BY a.ciKey, b.ciputAccount)  AS z INNER JOIN ags_accnt AS x ON z.ciputAccount = x.account_num)  AS y LEFT JOIN ags_cnInvAccnt AS ac ON (y.account_key = ac.ciaAccnt) AND (y.ciKey = ac.ciaCnInv) WHERE (((ac.ciaKey) Is Null)))  AS d INNER JOIN cipuCn_CtptCnOneInvOne ON d.ciKey = cipuCn_CtptCnOneInvOne.ciKey GROUP BY d.ciKey, d.ciputAccount, d.account_key)  AS h LEFT JOIN (SELECT q.ciKey, q.CntrPrtNum, q.CntrPrtName, q.CnName, q.cn_key, q.ciputCnInv, 1 AS countRel FROM cipuCn_CtptCnOneInvOne AS q)  AS j ON h.ciKey = j.ciKey;
